declare(strict_types=1);header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');$origin=$_SERVER['HTTP_ORIGIN']??'';$host=strtolower($_SERVER['HTTP_HOST']??'');if($host!=='neu.koblenzer-puppenspiele.de'||($origin!==''&&$origin!=='https://neu.koblenzer-puppenspiele.de')){http_response_code(403);echo json_encode(['error'=>'forbidden']);exit;}$file=__DIR__.'/.editor-state.json';$historyDir=__DIR__.'/.editor-history';function readState(string $p):?array{if(!is_file($p))return null;$d=json_decode((string)file_get_contents($p),true);return is_array($d)?$d:null;}function historyList(string $dir):array{if(!is_dir($dir))return [];$out=[];foreach(glob($dir.'/*.json')?:[] as $p){$d=readState($p);if($d)$out[]=['id'=>basename($p,'.json'),'savedAt'=>$d['savedAt']??null,'version'=>$d['version']??3];}usort($out,fn($a,$b)=>strcmp((string)$b['savedAt'],(string)$a['savedAt']));return array_slice($out,0,50);}$method=$_SERVER['REQUEST_METHOD'];$action=$_GET['action']??'';if($method==='GET'&&$action==='history'){echo json_encode(['ok'=>true,'versions'=>historyList($historyDir)],JSON_UNESCAPED_UNICODE);exit;}if($method==='GET'&&$action==='version'){$id=preg_replace('/[^0-9A-Za-z_-]/','',$_GET['id']??'');$d=$id!==''?readState($historyDir.'/'.$id.'.json'):null;if(!$d){http_response_code(404);echo json_encode(['error'=>'version not found']);exit;}$d['ok']=true;echo json_encode($d,JSON_UNESCAPED_UNICODE);exit;}if($method==='GET'){$d=readState($file);if(!$d){echo json_encode(['ok'=>true,'exists'=>false,'version'=>4]);exit;}$d['ok']=true;$d['exists']=true;echo json_encode($d,JSON_UNESCAPED_UNICODE);exit;}if($method!=='PUT'){http_response_code(405);exit;}$input=json_decode((string)file_get_contents('php://input'),true);if(!is_array($input)||!is_string($input['html']??null)||strlen($input['html'])>2000000){http_response_code(422);echo json_encode(['error'=>'invalid payload']);exit;}$layout=is_array($input['layout']??null)?$input['layout']:[];$header=is_string($in